  modal(["集结远征队","ASSEMBLE THE EXPEDITION"],["选择你的先锋，决定深入深渊的方式。每一次归来，都会让下一次远征更强。","Choose your vanguard and how you will descend. Every return strengthens the next expedition."],`
    <div class="menu-atmosphere" aria-hidden="true"><i></i><i></i><i></i></div>
    <div class="menu-command"><span>${tx("远征指挥部 · 账号进度已连接","EXPEDITION COMMAND · ACCOUNT LINKED")}</span><div class="save-actions menu-nav"><button id="menu-language">${profile.locale==="en"?"简体中文":"English"}</button><button id="menu-warehouse">${tx("仓库与装备","ARMORY")}</button><button id="menu-codex">${tx("图鉴","CODEX")}</button><button id="menu-achievements">${tx("成就","ACHIEVEMENTS")}</button></div></div>
    ${saveError?`<p class="menu-error" role="alert">${esc(saveError)}</p>`:""}
    <div class="menu-preparation"><section><div class="menu-section-title"><span>01</span><b>${tx("设定远征协议","EXPEDITION PROTOCOL")}</b></div><div class="setup"><label>${tx("模式","Mode")}<select id="run-mode"><option value="expedition">${tx("八层远征","Eight-floor Expedition")}</option><option value="endless">${tx("无尽深渊 · 可主动撤离","Endless Abyss · Extract anytime")}</option></select></label><label>${tx("难度","Difficulty")}<select id="difficulty">${Object.entries(DIFFICULTIES).map(([id,d])=>`<option value="${id}" ${id==="adventurer"?"selected":""}>${esc(label(d.name))}</option>`).join("")}</select></label><label class="seed-field">${tx("路线种子（可留空）","Route seed (optional)")}<input id="seed" maxlength="100" placeholder="${tx("输入种子仅生成新路线","A seed starts a NEW route")}"></label></div></section><aside><div class="menu-section-title"><span>02</span><b>${tx("预计带回物资","EXPECTED EXTRACTION")}</b></div><div class="loot-preview" id="loot-preview"></div><div class="save-actions menu-saves">${hasLocalSave()?`<button class="primary" id="resume-run">${tx("继续远征","CONTINUE RUN")}</button><button id="raw-backup">${tx("备份存档","BACKUP SAVE")}</button>`:""}<button id="import-menu">${tx("导入存档","IMPORT SAVE")}</button></div></aside></div>
    <div class="roster-heading"><div class="menu-section-title"><span>03</span><b>${tx("选择先锋","CHOOSE YOUR VANGUARD")}</b></div><small>${tx("选择角色后立即进入深渊","SELECT A HERO TO BEGIN")}</small></div>
    <div class="cards hero-grid">${Object.entries(HEROES).filter(([id])=>id!=="creator"||creatorUnlocked).map(([id,h],index)=>`<button class="card hero-choice" data-hero="${id}"><span class="hero-index">0${index+1}</span><span class="tag">${esc(h.key)}</span><strong>${esc(tx(h.name,h.enName))}</strong><small><b>${tx("生命","HP")} ${h.hp}</b><b>${tx("攻击","ATK")} ${h.attack}</b><span>${esc(tx(h.passive,h.enPassive))}</span><em>${h.skills.map(s=>esc(nameOfSkill(s))).join(" · ")}</em></small><span class="deploy-label">${tx("选择并出征","SELECT · DEPLOY")} →</span></button>`).join("")}</div>
    ${creatorUnlocked?"":`<div class="secret"><input id="creator-code" placeholder="${tx("已知隐藏口令？在这里输入","Know a secret code? Enter it here")}" aria-label="${tx("隐藏角色口令","Secret character code")}"><button id="unlock-creator">${tx("确认","Confirm")}</button></div>`}<nav class="menu-bottom-links" aria-label="${tx("扩展入口","Extra destinations")}"><a class="menu-art-lab" href="/art-test/">✦ <span>${tx("测试馆","ART LAB")}</span><small>${tx("角色动作 · 怪物 · 战斗特效","RIGS · ENEMIES · COMBAT FX")}</small> →</a><a class="back" href="/legacy/">← ${tx("打开旧版存档","Open legacy save")}</a></nav>`);
  $("overlay").classList.add("main-menu-overlay");$("overlay").querySelector(".modal").classList.add("main-menu");
  document.querySelectorAll("[data-hero]").forEach(button=>{const image=document.createElement("img");image.className="hero-choice-art";image.src=HERO_ART[button.dataset.hero];image.alt="";image.loading="eager";button.prepend(image);});
  bind("[data-hero]",button=>{if(hasLocalSave()&&!confirm(tx("开始新远征会替换本地续局，确定吗？","Starting a new run replaces the local save. Continue?")))return;newRun(button.dataset.hero,$("seed").value,$("difficulty").value,$("run-mode").value);});
  $("seed").value=previousSeed;$("difficulty").value=previousDifficulty;$("run-mode").value=previousMode;const updatePreview=()=>$("loot-preview").innerHTML=lootPreview($("difficulty").value);$("difficulty").onchange=updatePreview;updatePreview();
  $("menu-language").onclick=()=>$("language").click();$("menu-warehouse").onclick=()=>openArchive("warehouse");$("menu-codex").onclick=()=>openArchive("codex");$("menu-achievements").onclick=()=>openArchive("achievements");
  $("raw-backup")?.addEventListener("click",()=>{try{const raw=localStorage.getItem(BETA_RUN_KEY),url=URL.createObjectURL(new Blob([raw],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download="abyss-original-save-backup.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{saveError=tx("无法读取原存档","Cannot read original save");render();}});
  $("resume-run")?.addEventListener("click",()=>restoreRun());$("import-menu").onclick=()=>$("import-file").click();
